package com.flashsale.coupon;
import com.flashsale.common.security.Principal; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service class CouponTemplateService {private final CouponTemplateRepository repo;CouponTemplateService(CouponTemplateRepository r){repo=r;}private void op(Principal p){if(p==null||!p.canManageBusiness())throw new IllegalArgumentException("FORBIDDEN");}
 @Transactional CouponTemplate create(Principal p,CouponTemplate x){op(p);if(x.discountMinor()<=0||x.thresholdMinor()<0||x.discountMinor()>x.thresholdMinor()&&x.thresholdMinor()>0||x.issueLimit()<=0||x.claimLimitPerUser()<=0||x.claimStartsAt()==null||!x.claimStartsAt().isBefore(x.claimEndsAt())||!x.useStartsAt().isBefore(x.useEndsAt()))throw new IllegalArgumentException("VALIDATION_ERROR");return repo.create(new CouponTemplate(0,x.name(),x.thresholdMinor(),x.discountMinor(),x.issueLimit(),x.claimLimitPerUser(),x.claimStartsAt(),x.claimEndsAt(),x.useStartsAt(),x.useEndsAt(),"DRAFT",p.userId()));}
 @Transactional CouponTemplate update(Principal p,long id,CouponTemplate x){op(p);if(repo.get(id)==null)throw new IllegalArgumentException("COUPON_TEMPLATE_NOT_FOUND");CouponTemplate y=repo.update(id,new CouponTemplate(id,x.name(),x.thresholdMinor(),x.discountMinor(),x.issueLimit(),x.claimLimitPerUser(),x.claimStartsAt(),x.claimEndsAt(),x.useStartsAt(),x.useEndsAt(),null,p.userId()));if(y==null)throw new IllegalArgumentException("COUPON_TEMPLATE_ALREADY_ISSUED");return y;}
 @Transactional CouponTemplate status(Principal p,long id,String s){op(p);if(!s.equals("PAUSED")&&!s.equals("ACTIVE"))throw new IllegalArgumentException("VALIDATION_ERROR");CouponTemplate y=repo.status(id,s,p.userId());if(y==null)throw new IllegalArgumentException("COUPON_TEMPLATE_NOT_FOUND");return y;}CouponTemplate get(long id){CouponTemplate y=repo.get(id);if(y==null)throw new IllegalArgumentException("COUPON_TEMPLATE_NOT_FOUND");return y;}List<CouponTemplate> list(boolean a){return repo.list(a);}}
